(1217,1115,'_form','<div class=\"cf7-newsletter-wrap\">\n    <div class=\"cf7-input-box\">\n        <span class=\"jos-newsletter-icon\">\n            <svg width=\"22\" height=\"18\" viewBox=\"0 0 24 20\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                <rect x=\"1\" y=\"1\" width=\"22\" height=\"18\" rx=\"2\" stroke=\"#e8631b\" stroke-width=\"2\"/>\n                <path d=\"M2 3L12 11L22 3\" stroke=\"#e8631b\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n            </svg>\n        </span>\n        [email* your-email placeholder \"Input your email address\"]\n    </div>\n    [submit \"SUBSCRIBE\"]\n</div>'),
(1218,1115,'_mail','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:49:\"Cảm ơn bạn đã đăng ký nhận bản tin!\";s:6:\"sender\";s:41:\"[_site_title] <wordpress@wordpress.local>\";s:9:\"recipient\";s:20:\"nhanbao410@gmail.com\";s:4:\"body\";s:3167:\"<div style=\"background-color: #f4f6f9; padding: 40px 15px; font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif; color: #333333; line-height: 1.6;\">\n    <div style=\"max-width: 600px; margin: 0 auto; background-color: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.06);\">\n        \n        <!-- Header màu cam chuẩn thương hiệu -->\n        <div style=\"background: linear-gradient(135deg, #ea6b1d 0%, #ff8336 100%); padding: 35px 25px; text-align: center; color: #ffffff;\">\n            <h1 style=\"margin: 0; font-size: 26px; font-weight: 800; letter-spacing: 1px; text-transform: uppercase;\">GROUP B RECRUITING</h1>\n            <p style=\"margin: 8px 0 0; font-size: 15px; opacity: 0.95;\">Cầu Nối Cơ Hội Việc Làm & Nhân Tài Hàng Đầu</p>\n        </div>\n\n        <!-- Nội dung thư -->\n        <div style=\"padding: 35px 30px;\">\n            <h2 style=\"margin-top: 0; color: #ea6b1d; font-size: 21px; font-weight: 700;\">Chào mừng bạn đến với Bản tin Group B! 🎉</h2>\n            \n            <p style=\"font-size: 15px; color: #555555;\">\n                Xin chào, chúng tôi đã nhận được yêu cầu đăng ký nhận bản tin việc làm từ email <strong>[your-email]</strong> của bạn.\n            </p>\n            \n            <div style=\"background-color: #fff8f3; border-left: 4px solid #ea6b1d; padding: 15px 18px; margin: 25px 0; border-radius: 4px;\">\n                <p style=\"margin: 0; font-size: 14.5px; color: #444444;\">\n                    🌟 <strong>Bạn sẽ nhận được gì từ chúng tôi?</strong><br>\n                    • Cập nhật các vị trí tuyển dụng mới nhất hàng tuần.<br>\n                    • Xu hướng mức lương và nhu cầu thị trường lao động.<br>\n                    • Mẹo viết CV và phỏng vấn chuyên nghiệp.\n                </p>\n            </div>\n\n            <!-- Nút bấm hành động -->\n            <div style=\"text-align: center; margin: 35px 0 25px;\">\n                <a href=\"http://localhost:8080/jobs\" style=\"background-color: #ea6b1d; color: #ffffff; text-decoration: none; padding: 14px 32px; font-size: 15px; font-weight: 700; border-radius: 4px; display: inline-block; letter-spacing: 0.5px; text-transform: uppercase;\">\n                    Khám Phá Việc Làm Ngay\n                </a>\n            </div>\n\n            <p style=\"font-size: 14px; color: #777777; margin-bottom: 0;\">\n                Nếu bạn có bất kỳ câu hỏi nào hoặc muốn đăng tin tuyển dụng, đừng ngần ngại phản hồi trực tiếp qua email này.\n            </p>\n        </div>\n\n        <!-- Footer thư -->\n        <div style=\"background-color: #f9f9fb; padding: 20px; text-align: center; font-size: 13px; color: #888888; border-top: 1px solid #eeeeee;\">\n            <p style=\"margin: 0 0 6px;\">© 2026 <strong>Group B Recruiting</strong>. All rights reserved.</p>\n            <p style=\"margin: 0; font-size: 12px; color: #aaaaaa;\">Bạn nhận được email này vì đã đăng ký bản tin tại website của chúng tôi.</p>\n        </div>\n\n    </div>\n</div>\";s:18:\"additional_headers\";s:71:\"Reply-To: [your-email]\nCc: tn6879065@gmail.com, dangvanha123b@gmail.com\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:1;}'),
